#!/usr/bin/env python3
import csv, json, re
from collections import defaultdict
from pathlib import Path

DATA = Path('/app/data')
OUT = Path('/app/output/solution.json')

# Evidence is intentionally a short literal source span. Patterns use terms printed
# in the codebooks where possible, which keeps the normalization auditable.
RULES = [
    ('FIXTURE_CONTACT', re.compile(r'fixture|fixtur|接触不良|接處不良', re.I)),
    ('PROBE_WORN', re.compile(r'probe worn|探针磨损', re.I)),
    ('OPEN', re.compile(r'\bopen\b|开路|\bOS\b', re.I)),
    ('SHORT', re.compile(r'\bshort\b|短路|短露|\bbridge\b|桥连', re.I)),
    ('COLD_SOLDER', re.compile(r'cold solder|虚焊|虚汉|浮高', re.I)),
    ('FLASH_FAIL', re.compile(r'flash write|program/flash|program/flahs|program fail|烧录失败|写入失败', re.I)),
    ('CHECKSUM_FAIL', re.compile(r'\bCRC\b|checksum|校验失败', re.I)),
    ('BOOT_FAIL', re.compile(r'boot fail(?:ed)?|cannot boot|OS fail|启动失败|启动不了|开机启动', re.I)),
    ('VERSION_MISMATCH', re.compile(r'version mismatch|wrong FW|版本不符|下错程序', re.I)),
    ('LEAKAGE', re.compile(r'Hi[ -]?Pot|\bleakage\b|漏电', re.I)),
    ('CURRENT_HIGH', re.compile(r'idle current|current high|静态电流|功耗高', re.I)),
    ('CAL_DATA_FAIL', re.compile(r'RF cal data|校准数据', re.I)),
    ('CONNECTOR_WEAR', re.compile(r'connector wear|插拔', re.I)),
    ('CONTAMINATION', re.compile(r'contamination|\bresidue\b|助焊剂', re.I)),
    ('MISSING', re.compile(r'missing component|少件|漏贴', re.I)),
    ('REVERSED', re.compile(r'polarity reversed|\breversed\b|反向|装反', re.I)),
    ('ESD', re.compile(r'\bESD\b|静电', re.I)),
    ('PRESSURE_MARK', re.compile(r'pressure mark|pad damage|压伤', re.I)),
    ('HIGH_RES', re.compile(r'HIGH_RES', re.I)),
]

# Phrases that describe a possible mechanism do not establish a separate short.
def valid_match(category, text, match):
    if category == 'SHORT':
        before = text[max(0, match.start()-18):match.start()].lower()
        if 'partial ' in before or '疑似' in before[-4:] or '趋势' in text[match.end():match.end()+3]:
            return False
    if category == 'OPEN' and match.group(0).lower() == 'os':
        after = text[match.end():match.end()+8].lower()
        if re.match(r'\s*fail', after):
            return False
    return True

books = {}
for p in DATA.glob('codebook_*.csv'):
    rows = list(csv.DictReader(p.open(encoding='utf-8-sig', newline='')))
    prod = rows[0]['product_id']
    books[prod] = rows

by_category = {}
for prod, rows in books.items():
    d = defaultdict(list)
    for row in rows:
        d[row['category_lv2']].append(row)
    by_category[prod] = d

def components(label):
    # The component is the text after the colon and before a slash.
    if ':' not in label:
        return set()
    head = label.split(':', 1)[1].split('/', 1)[0].strip()
    return {head.upper()} if re.fullmatch(r'[A-Za-z]+\d+', head) else set()

def choose_code(prod, category, station, test_item, raw):
    candidates = by_category[prod].get(category, [])
    if not candidates:
        return None, 'not_in_product'
    distinct_labels = sorted({r['standard_label'] for r in candidates})
    specific = category in {'OPEN', 'SHORT', 'COLD_SOLDER', 'MISSING', 'REVERSED'}
    selected_label = None
    method = 'direct_category'

    if specific:
        upper_raw = raw.upper()
        # An explicitly named component is the strongest discriminator.
        explicit = []
        for label in distinct_labels:
            comps = components(label)
            if any(re.search(r'(?<![A-Z0-9_])' + re.escape(c) + r'(?![A-Z0-9_])', upper_raw) for c in comps):
                explicit.append(label)
        if len(explicit) == 1:
            selected_label, method = explicit[0], 'explicit_component'

        # Electrical labels can often be resolved directly by the named signal.
        if selected_label is None and category in {'OPEN', 'SHORT'}:
            signal_hits = [label for label in distinct_labels
                           if re.search(r'(?<![A-Z0-9_])' + re.escape(test_item.upper()) + r'(?![A-Z0-9_])', label.upper())]
            if len(signal_hits) == 1:
                selected_label, method = signal_hits[0], 'signal_match'

        # For cold solder, a signal may identify one component across electrical
        # labels, but only use it if that component has one cold-solder label.
        if selected_label is None and category == 'COLD_SOLDER':
            linked_components = set()
            for other in by_category[prod].get('OPEN', []) + by_category[prod].get('SHORT', []):
                if re.search(r'(?<![A-Z0-9_])' + re.escape(test_item.upper()) + r'(?![A-Z0-9_])', other['standard_label'].upper()):
                    linked_components |= components(other['standard_label'])
            linked_labels = [label for label in distinct_labels if components(label) & linked_components]
            if len(linked_labels) == 1:
                selected_label, method = linked_labels[0], 'signal_component_inference'

        # Station filtering is useful only if it leaves one genuinely distinct label.
        if selected_label is None:
            in_scope_labels = sorted({r['standard_label'] for r in candidates if station in r['station_scope'].split(';')})
            if len(in_scope_labels) == 1:
                selected_label, method = in_scope_labels[0], 'station_unique_label'

        if selected_label is None:
            return None, 'ambiguous_specific_label'
    else:
        # Duplicate codes with the same label are aliases; choose the lowest code.
        if len(distinct_labels) != 1:
            return None, 'ambiguous_category'
        selected_label = distinct_labels[0]

    rows = sorted((r for r in candidates if r['standard_label'] == selected_label), key=lambda r: r['code'])
    chosen = rows[0]
    aliases = len(rows)
    in_scope = station in chosen['station_scope'].split(';')
    return chosen, (method, aliases, in_scope)

def confidence_for(meta, evidence):
    method, aliases, in_scope = meta
    score = 0.93
    if aliases > 1:
        score -= 0.05
    if method == 'signal_match':
        score -= 0.06
    elif method == 'signal_component_inference':
        score -= 0.12
    elif method == 'station_unique_label':
        score -= 0.14
    if not in_scope:
        score -= 0.16
    if evidence.lower() in {'fixtur', '接處不良', '短露', '虚汉'} or 'flahs' in evidence.lower():
        score -= 0.10
    return round(max(0.58, score), 2)

def events_for(text):
    events = []
    for category, pattern in RULES:
        matches = [m for m in pattern.finditer(text) if valid_match(category, text, m)]
        if matches:
            # One category occurrence captures translated or repeated restatements.
            m = matches[0]
            events.append((m.start(), m.end(), category, m.group(0)))
    events.sort(key=lambda x: (x[0], x[1]))
    return events

records = []
with (DATA / 'test_center_logs.csv').open(encoding='utf-8-sig', newline='') as f:
    for row in csv.DictReader(f):
        text = row['raw_reason_text']
        normalized = []
        events = events_for(text)
        if not events:
            events = [(0, len(text), 'UNCLASSIFIED', text)]
        for _, _, category, evidence in events:
            chosen, meta = choose_code(row['product_id'], category, row['station'], row['test_item'], text) if category != 'UNCLASSIFIED' else (None, 'no_supported_evidence')
            if chosen is None:
                reason = {
                    'ambiguous_specific_label': 'The defect class is recognizable, but the product codebook does not identify one standard label from this signal and station.',
                    'not_in_product': 'The phrase describes a class that is not present in this product codebook.',
                    'ambiguous_category': 'The product codebook leaves multiple distinct labels for this evidence.',
                    'no_supported_evidence': 'No product-codebook phrase is supported strongly enough by the reported text.',
                }.get(meta, 'The available evidence does not identify one product-codebook label.')
                pred_code, pred_label = 'UNKNOWN', ''
                conf = 0.31 if category != 'UNCLASSIFIED' else 0.18
                rationale = f"{reason} Context: station={row['station']}, test_item={row['test_item']}."
            else:
                pred_code, pred_label = chosen['code'], chosen['standard_label']
                conf = confidence_for(meta, evidence)
                method, aliases, in_scope = meta
                support = {
                    'direct_category': 'The source span directly names the codebook defect class',
                    'explicit_component': 'The source text explicitly names the component in the standard label',
                    'signal_match': 'The reported signal and defect class match one standard label',
                    'signal_component_inference': 'The signal-to-component association leaves one cold-solder label',
                    'station_unique_label': 'The defect class and station leave one distinct standard label',
                }[method]
                alias_note = f"; code {pred_code} is the deterministic lowest of {aliases} equivalent code aliases" if aliases > 1 else ''
                scope_note = '' if in_scope else '; the station is outside the listed scope, so confidence is reduced'
                rationale = f"{support}{alias_note}{scope_note}. Context: station={row['station']}, test_item={row['test_item']}."
            normalized.append({
                'segment_id': f"{row['record_id']}-S{len(normalized)+1}",
                'span_text': evidence,
                'pred_code': pred_code,
                'pred_label': pred_label,
                'confidence': conf,
                'rationale': rationale,
            })
        records.append({
            'record_id': row['record_id'],
            'product_id': row['product_id'],
            'station': row['station'],
            'engineer_id': row['engineer_id'],
            'raw_reason_text': text,
            'normalized': normalized,
        })

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(json.dumps({'records': records}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'wrote {len(records)} records and {sum(len(r["normalized"]) for r in records)} segments to {OUT}')

